let uiLocale=(()=>{try{return localStorage.getItem("zapzap_ui_locale")==="pt-BR"?"pt-BR":"en"}catch{return"en"}})();
function translateUi(root=document.body){
  document.documentElement.lang=uiLocale;
  const nodes=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let node;
  while((node=nodes.nextNode())){
    if(node.parentElement?.closest("script,style"))continue;
    const original=node.__zapOriginal??node.textContent;
    node.__zapOriginal=original;
    if(uiLocale==="en"){node.textContent=original;continue}
    const clean=original.trim();
    if(!clean)continue;
    const match=translationsPtBr[clean]||(clean.match(/^(\\d+) demo records stored in this browser$/)?.[1]+' registros de demonstração salvos neste navegador');
    if(match&&match!=="undefined registros de demonstração salvos neste navegador")node.textContent=original.replace(clean,match);
  }
  root.querySelectorAll("input[placeholder],textarea[placeholder]").forEach(el=>{
    const original=el.dataset.zapOriginalPlaceholder??el.getAttribute("placeholder");
    el.dataset.zapOriginalPlaceholder=original;
    el.setAttribute("placeholder",uiLocale==="pt-BR"?(translationsPtBr[original]||original):original);
  });
  root.querySelectorAll("option").forEach(el=>{
    const original=el.dataset.zapOriginalOption??el.firstChild?.__zapOriginal??el.textContent;
    el.dataset.zapOriginalOption=original;
    if(!el.hasAttribute("value"))el.value=original;
    el.textContent=uiLocale==="pt-BR"?(translationsPtBr[original]||original):original;
  });
  const button=document.querySelector("#localeToggle");
  if(button){
    button.setAttribute("aria-label",uiLocale==="en"?"Mudar para português brasileiro":"Switch to English");
    button.setAttribute("title",uiLocale==="en"?"Português (Brasil)":"English");
    const flag=button.querySelector(".flag-icon");if(flag)flag.className="flag-icon "+(uiLocale==="en"?"flag-br":"flag-us");
    const label=button.querySelector("#languageLabel");if(label)label.textContent=uiLocale==="en"?"Português":"English";
  }
}
function toggleLocale(){
  uiLocale=uiLocale==="en"?"pt-BR":"en";
  try{localStorage.setItem("zapzap_ui_locale",uiLocale)}catch{}
  view();translateUi();
}

const defaults={business:"My Business",industry:"Other",agent:"Alex",tone:"Friendly & professional",language:"Auto detect",description:"Add your business description and services here.",products:"",hours:"",website:"",goals:["Answer FAQs","Capture leads","Book appointments"],aiProvider:"demo",busyMessage:"",storeHeadline:"Welcome to our business",storeDescription:"Explore our products and services, and ask our AI assistant for help.",storeImage:"",storeCategory:"Other",slug:"my-business",virtualNumber:"",humanPhone:"",sharePhone:false,allowCallbacks:true};
const initialLeads=[];
const initialConvos=[];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem("zapzap_"+key))??fallback}catch{return fallback}};
const state={settings:{...defaults,...read("settings",{})},leads:read("leads",initialLeads),catalog:read("catalog",[]),convos:read("convos",initialConvos),messages:[],callbackStage:null,callbackName:"",page:"overview",activeConv:0,notifications:true,role:null};
const save=(key,value)=>localStorage.setItem("zapzap_"+key,JSON.stringify(value));
const esc=(s)=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function toast(message){const el=$("#toast");el.textContent=uiLocale==="pt-BR"?(translationsPtBr[message]||message):message;el.classList.add("visible");clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove("visible"),3200)}
const field=(name,label,type="text")=>'<div class="field"><label for="'+name+'">'+label+'</label>'+(type==="textarea"?'<textarea id="'+name+'">'+esc(state.settings[name])+'</textarea>':'<input id="'+name+'" type="'+type+'" value="'+esc(state.settings[name])+'">')+'</div>';
function heading(eyebrow,title,subtitle,action=""){return '<div class="page-head"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p class="subtext">'+subtitle+'</p></div>'+action+'</div>'}
function view(){
  const gate=$("#demoGate");
  if(!state.role){$("#app").classList.add("hidden");gate.classList.remove("hidden");translateUi(gate);return;}
  $("#app").classList.remove("hidden");gate.classList.add("hidden");
  $("#demoRoleName").textContent=state.role==="admin"?"Super Admin • Demo":"Business Owner • Demo";
  const roleBtn=$("#demoSwitchRole");if(roleBtn)roleBtn.textContent=state.role==="admin"?"⇄ Preview Business Owner":"⇄ Preview Super Admin";
  const navNames={overview:"Overview",inbox:"Inbox",store:"My Store",leads:"Leads",studio:"AI Agent Studio",knowledge:"Knowledge Base",automations:"Automations",billing:"Plans & Billing",settings:"Settings"};
  $("#currentPage").textContent=navNames[state.page];$("#workspaceName").textContent=state.settings.business||"My Business";
  document.querySelectorAll(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.page===state.page));
  const views={overview,inbox,store,leads,studio,knowledge,automations,billing,settings};
  $("#content").innerHTML=views[state.page]();
  bind();
  translateUi();
}
