function leadTable(data){return '<div class="table-wrap"><table><thead><tr><th>CONTACT</th><th>INTEREST</th><th>STATUS</th><th>LAST ACTIVITY</th></tr></thead><tbody>'+data.map(l=>'<tr><td><b>'+esc(l.name)+'</b><small>'+esc(l.phone)+'</small></td><td>'+esc(l.interest)+'</td><td>'+badge(l.status)+'</td><td>'+esc(l.date)+'</td></tr>').join("")+'</tbody></table></div>'}

const virtualNumber=()=>{
  const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);
  return "+1 (202) 555-01"+String(bytes[0]%100).padStart(2,"0");
};
