function callbackReply(message,lang){
 const s=state.settings;
 const samples={
  en:{askName:"Sure. What name should our team use for your callback?",askPhone:"Thanks! What phone number can the team call?",saved:"Thanks! Your callback request was recorded in this demo. A real callback is not automatically scheduled.",no:"Callback requests are currently disabled. Please use the business's normal contact channels.",human:"I can help you reach a person.",number:"The business contact number is ",unavailable:"A direct phone number isn't available here. Would you like to request a callback?"},
  pt:{askName:"Claro! Qual nome nossa equipe deve usar para retornar sua ligação?",askPhone:"Obrigado! Para qual telefone a equipe pode ligar?",saved:"Obrigado! Seu pedido de retorno foi registrado nesta demonstração. Nenhuma ligação foi agendada automaticamente.",no:"Pedidos de retorno estão desativados. Use os canais normais da empresa.",human:"Posso ajudar você a falar com uma pessoa.",number:"O telefone de contato da empresa é ",unavailable:"Não há um telefone direto disponível aqui. Gostaria de solicitar um retorno?"},
  es:{askName:"¡Claro! ¿Qué nombre debe usar nuestro equipo para devolver la llamada?",askPhone:"¡Gracias! ¿A qué número podemos llamar?",saved:"¡Gracias! Tu solicitud se guardó en esta demostración. No se programó una llamada automáticamente.",no:"Las solicitudes de devolución de llamada están desactivadas. Usa los canales habituales del negocio.",human:"Puedo ayudarte a hablar con una persona.",number:"El teléfono de contacto de la empresa es ",unavailable:"No hay un teléfono directo disponible. ¿Quieres solicitar una devolución de llamada?"}
 };
 const t=samples[lang]||samples.en,raw=message.trim();
 if(state.callbackStage==="name"){
   if(raw.length<2)return t.askName;
   state.callbackName=raw.slice(0,80);state.callbackStage="phone";return t.askPhone;
 }
 if(state.callbackStage==="phone"){
   const sanitized=raw.replace(/[()\s.-]/g,"");
   if(!/^\+?\d{7,15}$/.test(sanitized))return t.askPhone;
   state.leads.unshift({name:state.callbackName||"Callback lead",phone:raw.slice(0,35),interest:"Callback request",status:"New",date:"Just now"});
   save("leads",state.leads);state.callbackName="";state.callbackStage=null;
   return t.saved;
 }
 if(/\b(call\s*(me|back)|callback|call me|call us|lig(a|ue)\s*(pra mim|para mim|de volta)|me liga|retorn(o|ar|e)\s*(a|uma)?\s*liga(c|ç)[aã]o|me llame|devolver\s*(la)?\s*llamada|ll[aá]mame)\b/i.test(raw)){
   if(!s.allowCallbacks)return t.no;
   state.callbackStage="name";return t.askName;
 }
 if(/\b(phone|telephone|number|human|real person|representative|agent|speak to someone|call someone|telefone|n[uú]mero|atendente|pessoa|humano|falar com|tel[eé]fono|n[uú]mero|persona|agente|hablar con alguien)\b/i.test(raw)){
   if(s.sharePhone&&/^\+?[\d\s().-]{7,35}$/.test(s.humanPhone||""))return t.number+s.humanPhone;
   return s.allowCallbacks?t.unavailable:t.human;
 }
 return null;
}


